mapper.select:
select ua.*,su.avatar as userAvatar,su.nickname as userName,su.phone as userPhone from ums_realname_auth ua left join sys_user su on su.id = ua.user_id where 1 = 1
and (su.nickname like CONCAT('%',#{paramCondition.keyword},'%') or su.phone like CONCAT('%',#{paramCondition.keyword},'%'))
AND ua.user_id = #{paramCondition.userId}
AND ua.auth_status = #{paramCondition.authStatus}
order by ua.create_time desc
